\begin{aligned}
\textsuperscript*{1} & \textsuperscript*{1} & \textsuperscript*{1} & \textsuperscript*{1} & \textsuperscript*{1} & \textsuperscript*{1} & \textsuperscript*{1} & \textsuperscript*{1} \\
